<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global Smartwatch Secondary Market Analysis — Q1 2026</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif; line-height: 1.6; color: #1a1a2e; background: #f8f9fa; }
        .container { max-width: 1100px; margin: 0 auto; padding: 40px 20px; }
        .header { background: linear-gradient(135deg, #1e88e5 0%, #0d47a1 100%); color: white; padding: 50px 40px; border-radius: 16px; margin-bottom: 40px; }
        .header h1 { font-size: 2.4em; margin-bottom: 10px; font-weight: 700; }
        .header p { font-size: 1.1em; opacity: 0.9; }
        .meta { display: flex; gap: 30px; margin-top: 20px; font-size: 0.9em; opacity: 0.8; }
        .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; margin-bottom: 40px; }
        .kpi-card { background: white; padding: 24px; border-radius: 12px; box-shadow: 0 2px 12px rgba(0,0,0,0.08); border-left: 4px solid #1e88e5; }
        .kpi-card.garmin { border-left-color: #43a047; }
        .kpi-card.samsung { border-left-color: #e53935; }
        .kpi-label { font-size: 0.85em; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
        .kpi-value { font-size: 1.8em; font-weight: 700; color: #1a1a2e; }

